static int test_hook_twins(void)
{
    static uint8_t pre[65536];
    int fail = 0, printed = 0, t, mv, cases = 4000, sub = 0;
    int sawLatched = 0, sawOneShot = 0, sawClamp = 0, sawAdvance = 0, sawEarlyStop = 0;
    int scale = 1, runClamp, runRecord, runLimit, runBack, runMerge[3], runGuard[2], runSteer, runSteerO, runSteerS, runSteerD, runSteerN, runCam, runSlot, runSahd;
    { const char* e = getenv("REVS_VALIDATE_CASES"); if (e) scale = atoi(e); }
    if (scale < 1) scale = 1;
    cases *= scale;
    register_fixture("hook_horizon_clamp");
    register_fixture("hook_steer_response_brands");
    register_fixture("hook_steer_response_oulton");
    register_fixture("hook_steer_response_snetter");
    register_fixture("hook_steer_response_doning");
    register_fixture("hook_steer_response_nurburg");
    register_fixture("hook_camera_scale_by_gradient");
    register_fixture("hook_span_cap_slot_test");
    register_fixture("hook_section_ahead_doning");
    register_fixture("hook_horizon_clamp_guarded_snetter");
    register_fixture("hook_horizon_clamp_guarded_nurburg");
    register_fixture("hook_record_horizon");
    register_fixture("hook_edge_walk_limit");
    register_fixture("hook_walk_back_gate");
    register_fixture("hook_merge_horizon_edges");
    register_fixture("hook_merge_horizon_edges_nurburg");
    register_fixture("hook_horizon_store_only");
    /* ⚠⚠ want() RESEEDS the stream, so it is called ONCE per fixture and NEVER in a loop
       condition — inside one it restarts the generator every iteration and every case is
       then the same case.  (It cost this fixture its `latched` and `early-stop` arms once.) */
    runClamp  = want("hook_horizon_clamp");
    runSteer  = want("hook_steer_response_brands");
    runSteerO = want("hook_steer_response_oulton");
    runSteerS = want("hook_steer_response_snetter");
    runSteerD = want("hook_steer_response_doning");
    runSteerN = want("hook_steer_response_nurburg");
    runCam    = want("hook_camera_scale_by_gradient");
    runSlot   = want("hook_span_cap_slot_test");
    runSahd   = want("hook_section_ahead_doning");
    runGuard[0] = want("hook_horizon_clamp_guarded_snetter");
    runGuard[1] = want("hook_horizon_clamp_guarded_nurburg");
    runRecord = want("hook_record_horizon");
    runLimit  = want("hook_edge_walk_limit");
    runBack   = want("hook_walk_back_gate");
    runMerge[0] = want("hook_merge_horizon_edges");
    runMerge[1] = want("hook_merge_horizon_edges_nurburg");
    runMerge[2] = want("hook_horizon_store_only");
    g_track = 1;                                    /* Brands Hatch — whose body this is */
    setenv("REVS_SMC_CONTINUE", "1", 1);

    for (t = 0; runClamp && t < cases; t++) {
        Cpu6502 c = zero_cpu();
        uint8_t horizon, y, cursor, latch;
        int i, walked;

        fill_random(pre);
        c.D = 0;                                    /* the geometry path, always binary */
        c.S = 0xFFu;
        c.A = (uint8_t)xs(); c.X = (uint8_t)xs();

        /* A plausible horizon and an edge_y row that mostly sits above it, so the walk
           actually walks instead of stopping on its first read. */
        horizon = (uint8_t)(0x38u + (xs() % 0x14u));
        pre[0x001F] = horizon;        /* horizon_extent */
        for (i = 0; i < 0x50; i++)
            pre[0x5F20 + i] = (uint8_t)(xs() % horizon);
        pre[0x004B]   = (uint8_t)(1u + (xs() % 0x28u));  /* span_end_index */
        pre[0x007F]               = (uint8_t)xs();  /* span_line_cursor */
        pre[0x0082]               = (uint8_t)xs();  /* the latch cell, live only inside */

        /* ⭐ SEED THE SMC EXTENT THE WAY BRANDS HATCH INSTALLS IT ($2542-$2545: its own
           `JSR $53F0` where Silverstone calls abs8, and `NOP` where Silverstone halves).
           The one-shot's half-width recompute goes through that site, so a random image
           there would trap instead of taking the arm the circuit really runs. */
        pre[0x2542] = 0x20u; pre[0x2543] = 0xF0u;
        pre[0x2544] = 0x53u; pre[0x2545] = 0xEAu;

        /* Entry Y: inside the seeded row, and bit 5 both ways — that bit decides whether
           the one-shot (object ceiling + half-width recompute) can fire at all. */
        y = (uint8_t)(0x0Au + (xs() % 0x40u));
        if (xs() & 1u) { y |= 0x20u;  sawLatched = 1; } else { y &= (uint8_t)~0x20u; }
        c.Y = y;

        /* ...and one case in four puts the horizon itself at the first point the walk reads,
           so the range exit fires before anything is clamped.  Without this the seeded row
           is entirely BELOW the horizon and that arm is unreachable by construction. */
        if ((xs() & 3u) == 0u)
            pre[0x5F20 + (uint8_t)(y - 1u)] = (uint8_t)(horizon + (xs() % 0x08u));

        /* Classify the arms the walk will take — fixture arithmetic, not the twin's. */
        cursor = 0; latch = (uint8_t)(y & 0x20u); walked = 0;
        for (i = 0; i < 256; i++) {
            uint8_t line = pre[0x5F20 + (uint8_t)(y - 1u - (uint8_t)i)];
            if (line >= horizon) { if (!walked) sawEarlyStop = 1; break; }
            walked = 1;
            if (line >= cursor) { cursor = line; sawAdvance = 1; }
            else { sawClamp = 1; if (!latch) { sawOneShot = 1; latch = 0x80u; } }
        }

        sub += diff_run("hook_horizon_clamp", pre, c,
                        hook_clamp_twin, hook_clamp_oracle,
                        LIVE_X | LIVE_Y, t, &printed);
    }
    fail += sub;
    if (runClamp)
    printf("%-32s %7d cases, %d mismatch (must be 0)  live=X,Y ($1946 keeps both)\n",
           "hook_horizon_clamp", cases, sub);
    if (runClamp && !(sawLatched && sawOneShot && sawClamp && sawAdvance && sawEarlyStop)) {
        printf("VACUOUS: hook_horizon_clamp missed an arm "
               "(latched %d one-shot %d clamp %d advance %d early-stop %d)\n",
               sawLatched, sawOneShot, sawClamp, sawAdvance, sawEarlyStop);
        fail++;
    }

    /* ------------------ $56C8 / $56C4, the same clamp released through Snetterton's and the
       Nurburgring's own yaw guard.  Both circuits' entries run through ONE fixture name. */
    {
        static const struct { const char* name; void (*twin)(void); void (*oracle)(void);
                              uint8_t lo, hi; int track; } CG[2] = {
            { "hook_horizon_clamp_guarded_snetter",
              hook_clampg_s_twin, hook_clampg_s_oracle, 0xC8u, 0x53u, 4 },
            { "hook_horizon_clamp_guarded_nurburg",
              hook_clampg_n_twin, hook_clampg_n_oracle, 0x55u, 0x55u, 5 },
        };
        int gsawOff = 0, gsawHalve = 0, gsawTurn = 0, gsawPitch = 0;
        int gsawEarlySeg = 0, gsawLateSeg = 0, k;

        for (k = 0; k < 2; k++) {
            int gsub = 0;
            if (!runGuard[k]) continue;
            g_track = CG[k].track;
            for (t = 0; t < cases / 2; t++) {
                Cpu6502 c = zero_cpu();
                uint8_t horizon, y;
                int i;

                fill_random(pre);
                c.D = 0;
                c.S = 0xFFu;
                c.A = (uint8_t)xs(); c.X = (uint8_t)xs();

                horizon = (uint8_t)(0x38u + (xs() % 0x14u));
                pre[0x001F] = horizon;
                for (i = 0; i < 0x50; i++)
                    pre[0x5F20 + i] = (uint8_t)(xs() % horizon);
                pre[0x004B] = (uint8_t)(1u + (xs() % 0x28u));
                pre[0x007F] = (uint8_t)xs();
                pre[0x0082] = (uint8_t)xs();

                /* This circuit's OWN $2542 patch — the half-width recompute goes through it. */
                pre[0x2542] = 0x20u; pre[0x2543] = CG[k].lo;
                pre[0x2544] = CG[k].hi; pre[0x2545] = 0xEAu;

                y = (uint8_t)(0x0Au + (xs() % 0x40u));
                if (xs() & 1u) y |= 0x20u; else y &= (uint8_t)~0x20u;
                c.Y = y;
                if ((xs() & 3u) == 0u)
                    pre[0x5F20 + (uint8_t)(y - 1u)] = (uint8_t)(horizon + (xs() % 0x08u));

                /* ⭐ THE GUARD IS THE POINT OF THIS FIXTURE, so its three outcomes are DRIVEN,
                   not left to a random byte: a random section_yaw is |yaw| >= $19 in 87% of
                   cases and the halve arm would be all but unreachable. */
                switch (xs() % 3u) {
                    case 0:  pre[0x0044] = (uint8_t)(0x19u + (xs() % 0x60u));  /* turning */
                             gsawTurn = 1; gsawOff = 1; break;
                    case 1:  pre[0x0044] = (uint8_t)(xs() % 0x19u);            /* straight... */
                             pre[0x000D] = (uint8_t)(xs() & 0x7Fu);            /* ...pitched up */
                             gsawPitch = 1; gsawOff = 1; break;
                    default: pre[0x0044] = (uint8_t)(xs() % 0x19u);
                             pre[0x000D] = (uint8_t)(0x80u | (xs() & 0x7Fu));  /* the halve arm */
                             gsawHalve = 1; break;
                }
                pre[0x0076] = (uint8_t)xs();          /* shared_temp_76 — the halved width */

                /* ⭐ The Nurburgring's guard has a THIRD test the others do not (segment < $30),
                   so the player's segment is driven both sides of it — a random $06FF is past
                   $30 five sixths of the time and its keep arm would barely be sampled. */
                if (xs() & 1u) { pre[0x06FF] = (uint8_t)(xs() % 0x30u);        gsawEarlySeg = 1; }
                else           { pre[0x06FF] = (uint8_t)(0x30u + (xs() % 0xD0u)); gsawLateSeg = 1; }

                gsub += diff_run(CG[k].name, pre, c,
                                 CG[k].twin, CG[k].oracle,
                                 LIVE_X | LIVE_Y, t, &printed);
            }
            fail += gsub;
            printf("%-32s %7d cases, %d mismatch (must be 0)  live=X,Y ($1946's)\n",
                   CG[k].name, cases / 2, gsub);
        }
        if ((runGuard[0] || runGuard[1]) &&
            !(gsawTurn && gsawPitch && gsawHalve && gsawOff && gsawEarlySeg && gsawLateSeg)) {
            printf("VACUOUS: the guarded clamp missed an arm (turning %d pitched %d halve %d "
                   "offscreen %d segment<$30 %d segment>=$30 %d)\n",
                   gsawTurn, gsawPitch, gsawHalve, gsawOff, gsawEarlySeg, gsawLateSeg);
            fail++;
        }
        g_track = 1;
    }

    /* -------------------------- $57A1, Brands Hatch's steering response (the $1593 SMC site) */
    if (runSteer) {
        int ssub = 0, sawBoost = 0, sawPlain = 0, sawZeroMul = 0, sawBigMul = 0;
        g_track = 1;
        for (t = 0; t < cases; t++) {
            Cpu6502 c = zero_cpu();
            uint8_t car;

            fill_random(pre);
            c.D = 0;                                /* the steering path, always binary */
            c.S = 0xFFu;
            c.A = (uint8_t)xs(); c.X = (uint8_t)xs(); c.Y = (uint8_t)xs();
            c.V = (uint8_t)(xs() & 1u);             /* ⭐ V must arrive BOTH ways: a zero
                                                       multiplier leaves the caller's V alone */

            car = (uint8_t)(xs() % 20u);            /* player_car — 0..19 */
            pre[0x006F] = car;
            /* Segment $20 is the boosted one; drive it both ways rather than leaving it to a
               random byte, which would hit $20 once in 256. */
            if (xs() & 1u) { pre[0x06E8 + car] = 0x20u; sawBoost = 1; }
            else           { pre[0x06E8 + car] = (uint8_t)(xs() | 1u); sawPlain = 1; }

            /* math_hi is the joystick reading the hook multiplies by. 0 exercises the
               "no ADC ran, V survives" path in both multiplies. */
            if ((xs() & 7u) == 0u) { pre[0x0075] = 0x00u; sawZeroMul = 1; }
            else                   { pre[0x0075] = (uint8_t)xs(); sawBigMul = 1; }
            pre[0x0074] = (uint8_t)xs();            /* math_lo — overwritten, but seeded anyway */

            ssub += diff_run("hook_steer_response_brands", pre, c,
                             hook_steer_twin, hook_steer_oracle,
                             LIVE_A | LIVE_X | LIVE_Y | LIVE_FLAGS, t, &printed);
        }
        fail += ssub;
        printf("%-32s %7d cases, %d mismatch (must be 0)  live=A,X,Y+flags\n",
               "hook_steer_response_brands", cases, ssub);
        if (!(sawBoost && sawPlain && sawZeroMul && sawBigMul)) {
            printf("VACUOUS: hook_steer_response_brands missed an arm "
                   "(segment $20 %d other %d zero reading %d non-zero %d)\n",
                   sawBoost, sawPlain, sawZeroMul, sawBigMul);
            fail++;
        }
    }

    /* --------------------------------- $57A1 (Oulton), the same curve, three special segments */
    if (runSteerO) {
        int osub = 0, saw48 = 0, sawB8 = 0, sawB0 = 0, sawDefault = 0, sawZeroMul = 0;
        g_track = 3;
        for (t = 0; t < cases; t++) {
            Cpu6502 c = zero_cpu();
            uint8_t car;

            fill_random(pre);
            c.D = 0;
            c.S = 0xFFu;
            c.A = (uint8_t)xs(); c.X = (uint8_t)xs(); c.Y = (uint8_t)xs();
            c.V = (uint8_t)(xs() & 1u);

            car = (uint8_t)(xs() % 20u);
            pre[0x006F] = car;
            /* All FOUR selection arms, driven explicitly — leaving the segment to a random byte
               would reach $48/$B8/$B0 about once in 85 cases between them. */
            switch (xs() & 3u) {
            case 0: pre[0x06E8 + car] = 0x48u; saw48 = 1; break;
            case 1: pre[0x06E8 + car] = 0xB8u; sawB8 = 1; break;
            case 2: pre[0x06E8 + car] = 0xB0u; sawB0 = 1; break;
            default: {
                uint8_t seg = (uint8_t)xs();
                if (seg == 0x48u || seg == 0xB8u || seg == 0xB0u) seg ^= 1u;
                pre[0x06E8 + car] = seg; sawDefault = 1;
                break;
            }
            }

            if ((xs() & 7u) == 0u) { pre[0x0075] = 0x00u; sawZeroMul = 1; }
            else                   { pre[0x0075] = (uint8_t)xs(); }
            pre[0x0074] = (uint8_t)xs();

            osub += diff_run("hook_steer_response_oulton", pre, c,
                             hook_steero_twin, hook_steero_oracle,
                             LIVE_A | LIVE_X | LIVE_Y | LIVE_FLAGS, t, &printed);
        }
        fail += osub;
        printf("%-32s %7d cases, %d mismatch (must be 0)  live=A,X,Y+flags\n",
               "hook_steer_response_oulton", cases, osub);
        if (!(saw48 && sawB8 && sawB0 && sawDefault && sawZeroMul)) {
            printf("VACUOUS: hook_steer_response_oulton missed an arm "
                   "($48 %d $B8 %d $B0 %d default %d zero reading %d)\n",
                   saw48, sawB8, sawB0, sawDefault, sawZeroMul);
            fail++;
        }
    }

    /* ------------------------- $57A1 (Snetterton), the curve plus the grip-loss pardon */
    if (runSteerS) {
        int nsub = 0, saw28in = 0, saw28out = 0, sawA8 = 0, sawA0 = 0, sawDef = 0, sawZeroMul = 0;
        g_track = 4;
        for (t = 0; t < cases; t++) {
            Cpu6502 c = zero_cpu();
            uint8_t car;

            fill_random(pre);
            c.D = 0;
            c.S = 0xFFu;
            c.A = (uint8_t)xs(); c.X = (uint8_t)xs(); c.Y = (uint8_t)xs();
            c.V = (uint8_t)(xs() & 1u);

            car = (uint8_t)(xs() % 20u);
            pre[0x006F] = car;
            pre[0x62FB] = (uint8_t)xs();            /* section_jump_history — the shifted byte */

            /* Five arms: segment $28 with the pardon earned and not earned, $A8, $A0, and the
               default.  $28's two sides differ only in car_seg_offset, so drive that too. */
            switch (xs() % 5u) {
            case 0: pre[0x06E8 + car] = 0x28u;
                    pre[0x0880 + car] = (uint8_t)(0x02u + (xs() % 0x30u));
                    saw28in = 1; break;
            case 1: pre[0x06E8 + car] = 0x28u;
                    pre[0x0880 + car] = (uint8_t)(xs() & 1u);
                    saw28out = 1; break;
            case 2: pre[0x06E8 + car] = 0xA8u; sawA8 = 1; break;
            case 3: pre[0x06E8 + car] = 0xA0u; sawA0 = 1; break;
            default: {
                uint8_t seg = (uint8_t)xs();
                if (seg == 0x28u || seg == 0xA8u || seg == 0xA0u) seg ^= 1u;
                pre[0x06E8 + car] = seg; sawDef = 1;
                break;
            }
            }

            if ((xs() & 7u) == 0u) { pre[0x0075] = 0x00u; sawZeroMul = 1; }
            else                   { pre[0x0075] = (uint8_t)xs(); }
            pre[0x0074] = (uint8_t)xs();

            nsub += diff_run("hook_steer_response_snetter", pre, c,
                             hook_steers_twin, hook_steers_oracle,
                             LIVE_A | LIVE_X | LIVE_Y | LIVE_FLAGS, t, &printed);
        }
        fail += nsub;
        printf("%-32s %7d cases, %d mismatch (must be 0)  live=A,X,Y+flags\n",
               "hook_steer_response_snetter", cases, nsub);
        if (!(saw28in && saw28out && sawA8 && sawA0 && sawDef && sawZeroMul)) {
            printf("VACUOUS: hook_steer_response_snetter missed an arm "
                   "($28 earned %d unearned %d $A8 %d $A0 %d default %d zero reading %d)\n",
                   saw28in, saw28out, sawA8, sawA0, sawDef, sawZeroMul);
            fail++;
        }
    }

    /* ------------------------ $5779 (Donington), four scales and five pardon conditions */
    if (runSteerD) {
        int dsub = 0, arm[7] = {0}, sawEarned = 0, sawUnearned = 0, sawZeroMul = 0;
        static const uint8_t DSEG[6] = { 0x10u, 0x58u, 0xA8u, 0x60u, 0xB0u, 0x18u };
        g_track = 2;
        for (t = 0; t < cases; t++) {
            Cpu6502 c = zero_cpu();
            uint8_t car, pick;

            fill_random(pre);
            c.D = 0;
            c.S = 0xFFu;
            c.A = (uint8_t)xs(); c.X = (uint8_t)xs(); c.Y = (uint8_t)xs();
            c.V = (uint8_t)(xs() & 1u);

            car = (uint8_t)(xs() % 20u);
            pre[0x006F] = car;
            pre[0x62FB] = (uint8_t)xs();            /* section_jump_history */

            /* Six named segments plus the default; the three THRESHOLD arms ($10/$58/$A8) need
               car_seg_offset driven both sides of their own threshold, which a random byte would
               only manage for $10. */
            pick = (uint8_t)(xs() % 7u);
            arm[pick] = 1;
            pre[0x06E8 + car] = (pick < 6u) ? DSEG[pick] : (uint8_t)0u;
            if (pick >= 6u) {
                uint8_t seg = (uint8_t)xs();
                while (seg == 0x10u || seg == 0x58u || seg == 0xA8u ||
                       seg == 0x60u || seg == 0xB0u || seg == 0x18u) seg ^= 1u;
                pre[0x06E8 + car] = seg;
            }
            {
                uint8_t thr = (pick == 1u) ? 0x27u : (pick == 2u) ? 0x21u : 0x01u;
                uint8_t off;
                /* ⭐ HALF the cases sit ON the threshold or one either side.  Spread uniformly
                   instead, an off-by-one in a threshold shows up in ~4 cases in 4000 — a thin
                   enough margin to be luck rather than a gate. */
                if (xs() & 1u) off = (uint8_t)(thr - 1u + (xs() % 3u));
                else if (xs() & 1u) off = (uint8_t)(thr + 1u + (xs() % 0x20u));
                else off = (uint8_t)(xs() % (unsigned)(thr + 1u));
                pre[0x0880 + car] = off;
                if (off > thr) sawEarned = 1; else sawUnearned = 1;
            }

            if ((xs() & 7u) == 0u) { pre[0x0075] = 0x00u; sawZeroMul = 1; }
            else                   { pre[0x0075] = (uint8_t)xs(); }
            pre[0x0074] = (uint8_t)xs();

            /* ⭐⭐ The $5791 PHA's byte at $01FF is residue, not a result (THE RESULTS RULE): the
               $57B2 PLA pops it inside this same hook and the twin carries the value in
               `segment`.  MEASURED as the only affected cell.  See the audit at the hook. */
            { static const uint16_t phaResidue[] = { 0x01FFu };
              set_ignore(phaResidue, 1);
              dsub += diff_run("hook_steer_response_doning", pre, c,
                               hook_steerd_twin, hook_steerd_oracle,
                               LIVE_A | LIVE_X | LIVE_Y | LIVE_FLAGS, t, &printed);
              set_ignore(0, 0); }
        }
        fail += dsub;
        printf("%-32s %7d cases, %d mismatch (must be 0)  live=A,X,Y+flags\n",
               "hook_steer_response_doning", cases, dsub);
        if (!(arm[0] && arm[1] && arm[2] && arm[3] && arm[4] && arm[5] && arm[6] &&
              sawEarned && sawUnearned && sawZeroMul)) {
            printf("VACUOUS: hook_steer_response_doning missed an arm "
                   "($10 %d $58 %d $A8 %d $60 %d $B0 %d $18 %d default %d "
                   "offset over %d under %d zero reading %d)\n",
                   arm[0], arm[1], arm[2], arm[3], arm[4], arm[5], arm[6],
                   sawEarned, sawUnearned, sawZeroMul);
            fail++;
        }
    }

    /* ------------------- $59D9 (the Nurburgring), the $1593 family's fifth and last member.
       Four per-segment scales, and the only member whose SHAPE is conditional: the ENGINE's Z
       (pushed at $59D9, restored at $56B5) chooses between a second plain scale and the
       square-then-double curve, so Z must arrive both ways. */
    if (runSteerN) {
        int nnsub = 0, arm[4] = {0}, sawZset = 0, sawZclear = 0, sawZeroMul = 0, sawTopBit = 0;
        static const uint8_t NSEG[3] = { 0x58u, 0x40u, 0xD0u };
        g_track = 5;
        for (t = 0; t < cases; t++) {
            Cpu6502 c = zero_cpu();
            uint8_t car, pick;

            fill_random(pre);
            c.D = 0;
            c.S = 0xFFu;
            c.A = (uint8_t)xs(); c.X = (uint8_t)xs(); c.Y = (uint8_t)xs();
            c.V = (uint8_t)(xs() & 1u);
            c.N = (uint8_t)(xs() & 1u);
            c.C = (uint8_t)(xs() & 1u);
            c.Z = (uint8_t)(xs() & 1u);             /* ⭐ the engine's Z picks the curve */
            if (c.Z) sawZset = 1; else sawZclear = 1;

            car = (uint8_t)(xs() % 20u);
            pre[0x006F] = car;                      /* player_car */
            /* The three named segments and the default, driven explicitly. */
            pick = (uint8_t)(xs() & 3u);
            arm[pick] = 1;
            if (pick < 3u) pre[0x06E8 + car] = NSEG[pick];
            else {
                uint8_t seg = (uint8_t)xs();
                if (seg == 0x58u || seg == 0x40u || seg == 0xD0u) seg ^= 1u;
                pre[0x06E8 + car] = seg;
            }

            /* The reading arrives in A and is what gets scaled; a zero product exercises the
               "no ADC ran, V survives" path, and a large one the doubling's carry-out. */
            if ((xs() & 7u) == 0u) { c.A = 0x00u; sawZeroMul = 1; }
            else if (xs() & 1u)    { c.A = (uint8_t)(0xC0u + (xs() % 0x40u)); sawTopBit = 1; }
            pre[0x0074] = (uint8_t)xs();            /* math_lo / math_hi, both overwritten */
            pre[0x0075] = (uint8_t)xs();

            nnsub += diff_run("hook_steer_response_nurburg", pre, c,
                              hook_steern_twin, hook_steern_oracle,
                              LIVE_A | LIVE_X | LIVE_Y | LIVE_FLAGS, t, &printed);
        }
        fail += nnsub;
        printf("%-32s %7d cases, %d mismatch (must be 0)  live=A,X,Y+flags\n",
               "hook_steer_response_nurburg", cases, nnsub);
        if (!(arm[0] && arm[1] && arm[2] && arm[3] &&
              sawZset && sawZclear && sawZeroMul && sawTopBit)) {
            printf("VACUOUS: hook_steer_response_nurburg missed an arm "
                   "($58 %d $40 %d $D0 %d default %d Z set %d Z clear %d "
                   "zero reading %d top-bit reading %d)\n",
                   arm[0], arm[1], arm[2], arm[3],
                   sawZset, sawZclear, sawZeroMul, sawTopBit);
            fail++;
        }
        g_track = 1;
    }

    /* ------------------------ $45CB's camera scale, driven through all five circuits' entries */
    if (runCam) {
        static const struct { void (*tw)(void); void (*or_)(void); unsigned char track; }
            CAM[5] = { { hook_cam_b_twin, hook_cam_b_oracle, 1 },
                       { hook_cam_d_twin, hook_cam_d_oracle, 2 },
                       { hook_cam_o_twin, hook_cam_o_oracle, 3 },
                       { hook_cam_s_twin, hook_cam_s_oracle, 4 },
                       { hook_cam_n_twin, hook_cam_n_oracle, 5 } };
        int csub = 0, k, sawSettled = 0, sawOther = 0, sawBorrow = 0, sawNoBorrow = 0;
        int sawPairCarry = 0, sawTop = 0;
        for (t = 0; t < cases; t++) {
            Cpu6502 c = zero_cpu();
            uint8_t stored, grad;

            fill_random(pre);
            c.D = 0;                                /* the camera path, always binary */
            c.S = 0xFFu;
            c.X = (uint8_t)xs(); c.Y = (uint8_t)xs();
            c.V = xs() & 1u; c.C = xs() & 1u; c.N = xs() & 1u;

            /* $45BF/$45C3/$45C7 store one of exactly three bytes, and only the $00 one takes
               the road-speed arm — so drive those three, not a random byte. */
            switch (xs() % 3u) {
            case 0:  stored = 0x00u; sawSettled = 1; break;
            case 1:  stored = 0x01u; sawOther = 1; break;
            default: stored = 0x7Fu; sawOther = 1; break;
            }
            c.A = stored;
            c.Z = (uint8_t)(stored == 0u);          /* the LDA's own Z, which the hook branches on */

            /* The gradient's SIGN decides the borrow, and track_dir_1[Y] EOR track_direction is
               what sets it — so drive both signs of both bytes rather than hoping. */
            grad = (uint8_t)xs();
            if (xs() & 1u) grad |= 0x80u; else grad &= 0x7Fu;
            pre[0x5500 + c.Y] = grad;               /* track_dir_1[Y] */
            pre[0x0025] = (uint8_t)((xs() & 1u) ? 0x80u : 0x00u);   /* track_direction */
            pre[0x0027] = (uint8_t)xs();            /* road_speed — the value being scaled */

            /* shared_temp_77's top bit is the pair's carry out; its low bit is what the ROL
               brings the doubling into.  Both matter, so both are driven. */
            if (xs() & 1u) { pre[0x0077] = (uint8_t)(xs() | 0x80u); sawTop = 1; }
            else           { pre[0x0077] = (uint8_t)(xs() & 0x7Fu); }
            /* What the doubled byte will be — recomputed from the same inputs the twin reads
               (so it cannot agree with a broken twin), for the arm counters below. */
            {
                uint8_t eor  = (uint8_t)(grad ^ pre[0x0025]);
                uint8_t mag  = (grad & 0x80u) ? (uint8_t)(-(int)grad) : grad;
                uint8_t high = (uint8_t)(((unsigned)mag * pre[0x0027]) >> 8);
                uint8_t sc   = (eor & 0x80u) ? (uint8_t)(-(int)high) : high;
                uint8_t byte = (stored == 0u) ? sc : stored;
                if (byte & 0x80u) sawPairCarry = 1;    /* the ASL's carry into the ROL */
                if (stored == 0u) { if (sc & 0x80u) sawBorrow = 1; else sawNoBorrow = 1; }
            }

            for (k = 0; k < 5; k++) {
                g_track = CAM[k].track;
                csub += diff_run("hook_camera_scale_by_gradient", pre, c,
                                 CAM[k].tw, CAM[k].or_,
                                 LIVE_A | LIVE_X | LIVE_Y | LIVE_FLAGS, t, &printed);
            }
        }
        fail += csub;
        printf("%-32s %7d cases x every circuit's entry, %d mismatch (must be 0)  "
               "live=A,X,Y+flags\n", "hook_camera_scale_by_gradient", cases, csub);
        if (!(sawSettled && sawOther && sawBorrow && sawNoBorrow && sawPairCarry && sawTop)) {
            printf("VACUOUS: hook_camera_scale_by_gradient missed an arm "
                   "(settled %d other %d borrow %d no-borrow %d A bit7 %d $77 bit7 %d)\n",
                   sawSettled, sawOther, sawBorrow, sawNoBorrow, sawPairCarry, sawTop);
            fail++;
        }
    }

    /* ------------------------------------ $2F23's slot test, both circuits' copies of the body */
    if (runSlot) {
        static const struct { void (*tw)(void); void (*or_)(void); unsigned char track; }
            SLOT[2] = { { hook_slot_d_twin, hook_slot_d_oracle, 2 },
                        { hook_slot_s_twin, hook_slot_s_oracle, 4 } };
        int lsub = 0, k, sawInherit = 0, sawFall = 0, sawEmpty = 0, sawFull = 0;
        int sawAbove8B = 0, sawBelow8B = 0, sawWrap = 0;
        for (t = 0; t < cases; t++) {
            Cpu6502 c = zero_cpu();
            uint8_t y, below;

            fill_random(pre);
            c.D = 0;
            c.S = 0xFFu;
            c.A = (uint8_t)xs(); c.X = (uint8_t)xs();
            c.N = xs() & 1u; c.Z = xs() & 1u; c.C = xs() & 1u; c.V = xs() & 1u;

            /* Y is a scan line 0..$4F, plus $FF — what `y--` leaves when the walk steps off
               the top, which span_cap_line only range-checks AFTER asking this question. */
            if ((xs() % 16u) == 0u) { y = 0xFFu; sawWrap = 1; }
            else                     y = (uint8_t)(xs() % 0x50u);
            c.Y = y;

            /* The line BELOW decides everything, so $8B gets half the cases and the two sides
               of the compare are named as well (C on the fallback path is the CMP's). */
            switch (xs() % 4u) {
            case 0: case 1: below = 0x8Bu; sawInherit = 1; break;
            case 2: below = (uint8_t)(0x8Cu + (xs() % 0x74u)); sawAbove8B = 1; sawFall = 1; break;
            default: below = (uint8_t)(xs() % 0x8Bu);         sawBelow8B = 1; sawFall = 1; break;
            }
            pre[0x5F61 + y] = below;

            /* ...and this line's own class, whose ZERO is the "still empty" answer. */
            if (xs() & 1u) { pre[0x5F60 + y] = 0x00u; sawEmpty = 1; }
            else           { pre[0x5F60 + y] = (uint8_t)(xs() | 1u); sawFull = 1; }

            for (k = 0; k < 2; k++) {
                g_track = SLOT[k].track;
                lsub += diff_run("hook_span_cap_slot_test", pre, c, SLOT[k].tw, SLOT[k].or_,
                                 LIVE_A | LIVE_X | LIVE_Y | LIVE_FLAGS, t, &printed);
            }
        }
        fail += lsub;
        printf("%-32s %7d cases x both circuits' entries, %d mismatch (must be 0)  "
               "live=A,X,Y+flags\n", "hook_span_cap_slot_test", cases, lsub);
        if (!(sawInherit && sawFall && sawEmpty && sawFull && sawAbove8B && sawBelow8B &&
              sawWrap)) {
            printf("VACUOUS: hook_span_cap_slot_test missed an arm "
                   "(inherit %d fallback %d empty %d full %d below>$8B %d below<$8B %d "
                   "Y wrap %d)\n", sawInherit, sawFall, sawEmpty, sawFull, sawAbove8B,
                   sawBelow8B, sawWrap);
            fail++;
        }
    }

    /* --------------------------------------- $53E9, Donington's double section step.
       ⚠ The CALLEE (build_section_ahead and the walk under it) is left at its Silverstone
       SMC bytes here: it is the same code on both sides of the diff, and the arm under test
       is the count compare in front of it.  walk_cluster_pre supplies a walk that can
       actually step, so the second build has somewhere to go. */
    if (runSahd) {
        static const uint16_t IGN[] = { 0x01FF };   /* build_road_section's PHP/PLP byte */
        int sawDouble = 0, sawSingle = 0, sawEdge = 0;
        sub = 0; printed = 0;
        setenv("REVS_SMC_CONTINUE", "1", 1);
        set_ignore(IGN, 1);
        g_track = 2;                                /* Donington */
        for (t = 0; t < cases; t++) {
            Cpu6502 c = zero_cpu();
            uint8_t count;

            fill_random(pre);
            walk_cluster_pre(pre);
            c.D = 0;                                /* the geometry path is always binary */
            c.S = 0xFFu;

            /* The count as $24DE's CMP left it: below $0C by construction on this arm, and
               sitting ON $0B or either side of it half the time. */
            count = (xs() & 1u) ? (uint8_t)(0x0Au + (xs() % 3u)) : (uint8_t)(xs() % 0x0Cu);
            pre[0x0013] = count;                    /* edge_nearest_section */
            if (count < 0x0Bu) sawDouble = 1; else sawSingle = 1;
            if (count == 0x0Au || count == 0x0Bu) sawEdge = 1;

            c.A = count;                            /* the hook's own input */
            c.X = (uint8_t)xs(); c.Y = (uint8_t)xs();
            c.N = xs() & 1u; c.V = xs() & 1u; c.Z = xs() & 1u; c.C = xs() & 1u;

            sub += diff_run("hook_section_ahead_doning", pre, c,
                            hook_sahd_twin, hook_sahd_oracle,
                            LIVE_A | LIVE_X | LIVE_Y | LIVE_S | LIVE_FLAGS, t, &printed);
        }
        set_ignore(0, 0);
        fail += sub;
        printf("%-32s %7d cases, %d mismatch (must be 0)  live=A,X,Y+flags\n",
               "hook_section_ahead_doning", cases, sub);
        if (!(sawDouble && sawSingle && sawEdge)) {
            printf("VACUOUS: hook_section_ahead_doning missed an arm "
                   "(double %d single %d on-the-edge %d)\n", sawDouble, sawSingle, sawEdge);
            fail++;
        }
    }

    /* ------------------------------------------------------- $56AF, the horizon recorder */
    if (runRecord) {
        static const uint16_t IGN[] = { 0x01FF };   /* the hook's own PHA/PLA byte */
        int sawRecord = 0, sawSuppressed = 0, sawEdge = 0;
        sub = 0; printed = 0;
        set_ignore(IGN, 1);
        for (t = 0; t < cases; t++) {
            Cpu6502 c = zero_cpu();
            uint8_t count;

            fill_random(pre);
            c.D = 0;
            c.S = 0xFFu;
            /* The section count straddling 12, with the threshold itself in the mix. */
            count = (uint8_t)(0x08u + (xs() % 0x09u));
            pre[0x0042] = count;                    /* shared_counter_42 */
            if (count >= 0x0Cu) sawSuppressed = 1; else sawRecord = 1;
            if (count == 0x0Cu || count == 0x0Bu) sawEdge = 1;
            c.A = (uint8_t)xs();                    /* the point's line, live in and out */
            c.Y = (uint8_t)xs();                    /* its index */
            c.X = (uint8_t)xs();

            sub += diff_run("hook_record_horizon", pre, c,
                            hook_rec_twin, hook_rec_oracle,
                            LIVE_A | LIVE_X | LIVE_Y | LIVE_N | LIVE_Z | LIVE_C, t, &printed);
            sub += diff_run("hook_record_horizon", pre, c,       /* $5755, the Nurburgring's */
                            hook_rec_n_twin, hook_rec_n_oracle,
                            LIVE_A | LIVE_X | LIVE_Y | LIVE_N | LIVE_Z | LIVE_C, t, &printed);
        }
        set_ignore(0, 0);
        fail += sub;
        printf("%-32s %7d cases x both circuits' entries, %d mismatch (must be 0)  "
               "live=A,X,Y,N,Z,C\n", "hook_record_horizon", cases, sub);
        if (!(sawRecord && sawSuppressed && sawEdge)) {
            printf("VACUOUS: hook_record_horizon missed an arm "
                   "(record %d suppressed %d threshold %d)\n",
                   sawRecord, sawSuppressed, sawEdge);
            fail++;
        }
    }

    /* ------------------------------------------------ $56BC, the walk's point-count limit.
       The stop arm is a compare and nothing else; the other arm is a whole resumed road walk,
       so the live mask is per-case: registers only where the hook really returns them. */
    if (runLimit) {
        static const uint16_t IGN[] = { 0x01FF };   /* build_road_section's PHP/PLP byte */
        int sawStop = 0, sawWalk = 0, sawThreshold = 0, sawNoCarry = 0, emitted = 0;
        int walkCases = cases / 8;                  /* each non-stop case runs a full walk */
        sub = 0; printed = 0;
        set_ignore(IGN, 1);
        for (t = 0; t < walkCases; t++) {
            Cpu6502 c = zero_cpu();
            uint8_t count;
            int shape = (t % 5 == 3) ? EDGE_HOOKED : (t % 5 == 4) ? EDGE_GARBAGE
                                                                  : EDGE_SILVERSTONE;
            int stopArm;
            unsigned mask;

            edge_pre(pre, shape);
            /* the count straddling $0A, the threshold itself included */
            count = (uint8_t)(0x06u + (xs() % 0x0Au));
            pre[0x0042] = count;                             /* shared_counter_42 */
            /* the walk state $2490 resumes on, as road_edge_walk_resume's fixture seeds it */
            pre[0x0012] = (xs() % 3) ? (uint8_t)(0x06u + (xs() % 0x20u)) : (uint8_t)xs();
            pre[0x0014] = (uint8_t)(xs() % 0xF0);            /* walk_prev_section */
            c.A = (uint8_t)xs();
            c.X = (uint8_t)(xs() % 0xF0);                    /* the section byte */
            c.Y = (uint8_t)xs();
            c.N = xs() & 1; c.V = xs() & 1; c.Z = xs() & 1;
            c.C = (uint8_t)(xs() & 1);                       /* the off-axis compare's carry */
            c.D = 0;
            c.S = 0xFFu;

            if (count == 0x0Au) sawThreshold = 1;
            if (!c.C) sawNoCarry = 1;
            stopArm = (c.C && count >= 0x0Au);
            if (stopArm) sawStop++; else sawWalk++;
            mask = stopArm ? (LIVE_A | LIVE_X | LIVE_Y | LIVE_S |
                              LIVE_N | LIVE_V | LIVE_Z | LIVE_C)
                           : LIVE_S;

            sub += diff_run("hook_edge_walk_limit", pre, c,
                            hook_lim_twin, hook_lim_oracle, mask, t, &printed);
            sub += diff_run("hook_edge_walk_limit", pre, c,      /* $5456, the Nurburgring's */
                            hook_lim_n_twin, hook_lim_n_oracle, mask, t, &printed);
            if (!stopArm && walk_emitted(pre, (const uint8_t*)mem)) emitted++;
        }
        set_ignore(0, 0);
        fail += sub;
        printf("%-32s %7d cases, %d mismatch (must be 0)  live=AXY+flags on the stop arm, "
               "mem-only on the walk (%d walked, %d emitted a point)\n",
               "hook_edge_walk_limit", walkCases, sub, sawWalk, emitted);
        if (!(sawStop && sawWalk && sawThreshold && sawNoCarry && emitted)) {
            printf("VACUOUS: hook_edge_walk_limit missed an arm "
                   "(stop %d walk %d threshold %d carry-clear %d emitted %d)\n",
                   sawStop, sawWalk, sawThreshold, sawNoCarry, emitted);
            fail++;
        }
    }

    /* -------------------------------------------------------- $55BD, the walk-back gate.
       Its pre-state is rebuild_walk_backward's (the routine it gates), plus the flag byte
       whose bit 7 is the gate itself, swept both ways. */
    if (runBack) {
        static const uint16_t IGN[] = { 0x01FF };   /* build_road_section's PHP/PLP byte */
        int sawGated = 0, sawRebuilt = 0, sawFwd = 0, sawBwd = 0;
        int backCases = cases / 20;                 /* each ungated case rebuilds 39 sections */
        sub = 0; printed = 0;
        set_ignore(IGN, 1);
        for (t = 0; t < backCases; t++) {
            Cpu6502 c = zero_cpu();
            uint8_t flags;
            int gated;

            fill_random(pre);
            walk_cluster_pre(pre);
            flags = (uint8_t)xs();
            if (xs() & 1u) flags |= 0x80u; else flags &= 0x7Fu;
            pre[0x0043] = flags;                             /* section_quad_flags */
            c.A = (uint8_t)xs(); c.X = (uint8_t)xs(); c.Y = (uint8_t)xs();
            c.N = xs() & 1; c.V = xs() & 1; c.Z = xs() & 1; c.C = xs() & 1;
            c.D = 0;
            c.S = 0xFFu;

            gated = (flags & 0x80u) != 0;
            if (gated) sawGated = 1; else sawRebuilt = 1;
            if (pre[0x0025] & 0x80u) sawBwd = 1; else sawFwd = 1;

            /* both entries: $55BD on the four Superior circuits, $53F3 on the Nurburgring */
            sub += diff_run("hook_walk_back_gate", pre, c,
                            hook_back_twin, hook_back_oracle,
                            gated ? (LIVE_A | LIVE_X | LIVE_Y | LIVE_S |
                                     LIVE_N | LIVE_V | LIVE_Z | LIVE_C)
                                  : LIVE_NONE,
                            t, &printed);
            sub += diff_run("hook_walk_back_gate", pre, c,
                            hook_back_n_twin, hook_back_n_oracle,
                            gated ? (LIVE_A | LIVE_X | LIVE_Y | LIVE_S |
                                     LIVE_N | LIVE_V | LIVE_Z | LIVE_C)
                                  : LIVE_NONE,
                            t, &printed);
        }
        set_ignore(0, 0);
        fail += sub;
        printf("%-32s %7d cases, %d mismatch (must be 0)  live=AXY+flags when gated, "
               "none when it rebuilds\n", "hook_walk_back_gate", backCases, sub);
        if (!(sawGated && sawRebuilt && sawFwd && sawBwd)) {
            printf("VACUOUS: hook_walk_back_gate missed an arm "
                   "(gated %d rebuilt %d fwd %d bwd %d)\n",
                   sawGated, sawRebuilt, sawFwd, sawBwd);
            fail++;
        }
    }

    /* -------------------------------------------------- $5772, the horizon edge merge.
       Its two indexed halves are the whole point, so the fixture randomises both and then
       forces the pull-in arm on some cases outright: with random azimuths the near side is
       behind the far side half the time, but the ENTRY POINT past 8 (one iteration at a bogus
       index — the shape the $2538 handover bug produced) needs asking for. */
    /* Three fixtures over the one address.  Variant 0 is the shared merge (Brands, Oulton,
       Snetterton), 1 the Nurburgring's merge with its style clear below point 6, 2 Donington's
       store-and-return.  Variant 2 shares the fan setup so its sabotages have somewhere to go
       wrong: a merge that runs when it should not is exactly what the fixture must catch. */
    for (mv = 0; mv < 3; mv++) {
        int sawPullIn = 0, sawLeave = 0, sawFull = 0, sawPastEnd = 0, sawWrap = 0;
        int sawLoTie = 0, sawClear = 0, sawNoClear = 0;
        static const char *const MERGE_NAME[3] = {
            "hook_merge_horizon_edges",
            "hook_merge_horizon_edges_nurburg",
            "hook_horizon_store_only"
        };
        static void (*const MERGE_TWIN[3])(void)   = { hook_merge_twin, hook_mergen_twin,
                                                       hook_merged_twin };
        static void (*const MERGE_ORACLE[3])(void) = { hook_merge_oracle, hook_mergen_oracle,
                                                       hook_merged_oracle };

        if (!runMerge[mv]) continue;
        sub = 0; printed = 0;
        for (t = 0; t < cases; t++) {
            Cpu6502 c = zero_cpu();
            uint8_t point;
            int i;

            fill_random(pre);
            c.D = 0;
            c.S = 0xFFu;

            /* the horizon fan: nine points on each side, azimuths that straddle each other */
            for (i = 0; i < 0x50; i++) {
                pre[0x5E40 + i] = (uint8_t)xs();                    /* edge_x_lo, both halves */
                /* edge_x_hi — mostly a small angle, sometimes anything: the exit V comes
                   from this subtract and a small-angle-only fixture can never overflow it. */
                pre[0x5E90 + i] = (xs() % 4u) ? (uint8_t)(xs() % 0x08u) : (uint8_t)xs();
                pre[0x5F20 + i] = (uint8_t)(xs() % 0x50u);          /* edge_y */
            }
            /* a quarter of the cases make the two hi bytes EQUAL, so the low byte decides —
               the arm a hi-byte-only compare would get wrong. */
            if ((xs() & 3u) == 0u)
                for (i = 0; i < 9; i++) pre[0x5E90 + EDGE_HALF_T + i] = pre[0x5E90 + i];
            /* ⭐ ...and an eighth make the two LOW bytes equal with full-range high bytes.
               The exit V is the high subtract's overflow, and its BORROW comes from the low
               subtract: the two differ only on a tie, and a tie with small angles cannot
               overflow, so without this arm a wrong borrow is unobservable (measured — the
               sabotage survived 4000 cases twice before this went in). */
            if ((xs() % 8u) == 0u) {
                for (i = 0; i < 9; i++) {
                    pre[0x5E40 + EDGE_HALF_T + i] = pre[0x5E40 + i];
                    pre[0x5E90 + i]               = (uint8_t)xs();
                    pre[0x5E90 + EDGE_HALF_T + i] = (uint8_t)xs();
                }
                sawLoTie = 1;
            }

            pre[0x0020] = (uint8_t)(xs() % 0x28u);                  /* horizon_index, the exit Y */

            /* the entry point: inside the fan most of the time, past its end sometimes, and
               $FF now and then (the INY wraps to 0 and the body runs the whole fan). */
            switch (xs() % 8u) {
                case 6:  point = (uint8_t)(0x09u + (xs() % 0x30u)); sawPastEnd = 1; break;
                case 7:  point = 0xFFu;                             sawWrap    = 1; break;
                default: point = (uint8_t)(xs() % 0x09u);
                         if (point == 0) sawFull = 1;               break;
            }
            c.Y = point;
            c.A = (uint8_t)(0x30u + (xs() % 0x20u));                /* the clamped horizon line */
            c.X = (uint8_t)xs();
            c.N = xs() & 1; c.V = xs() & 1; c.Z = xs() & 1; c.C = xs() & 1;

            /* which arm the first iteration takes — fixture arithmetic, not the twin's */
            {
                uint16_t nearAz = (uint16_t)(pre[0x5E40 + point] | (pre[0x5E90 + point] << 8));
                uint16_t farAz  = (uint16_t)(pre[0x5E40 + EDGE_HALF_T + point]
                                           | (pre[0x5E90 + EDGE_HALF_T + point] << 8));
                if ((uint16_t)(nearAz - farAz) & 0x8000u) sawPullIn = 1; else sawLeave = 1;
            }
            /* whether this entry point reaches a point below 6 at all — the Nurburgring's
               style clear only runs there, and $FF's wrap reaches every one of them. */
            if (point < 0x06u || point == 0xFFu) sawClear = 1; else sawNoClear = 1;

            sub += diff_run(MERGE_NAME[mv], pre, c,
                            MERGE_TWIN[mv], MERGE_ORACLE[mv],
                            LIVE_A | LIVE_X | LIVE_Y | LIVE_S |
                            LIVE_N | LIVE_V | LIVE_Z | LIVE_C, t, &printed);
        }
        fail += sub;
        printf("%-32s %7d cases, %d mismatch (must be 0)  live=A,X,Y,N,V,Z,C\n",
               MERGE_NAME[mv], cases, sub);
        if (!(sawPullIn && sawLeave && sawFull && sawPastEnd && sawWrap && sawLoTie
              && sawClear && sawNoClear)) {
            printf("VACUOUS: %s missed an arm "
                   "(pull-in %d leave %d from-0 %d past-end %d wrap %d lo-tie %d "
                   "below-6 %d at-or-above-6 %d)\n",
                   MERGE_NAME[mv], sawPullIn, sawLeave, sawFull, sawPastEnd, sawWrap,
                   sawLoTie, sawClear, sawNoClear);
            fail++;
        }
    }

    /* --------------------------------------- $5582 / $557F, the generator cursor's step.
       Four fixtures over one body: two state blocks x with and without the engine's own
       segment-direction step in front.  The run-length table gets a few ZERO entries because
       the 6502 walks it with a bottom-tested loop and a zero-length place is reachable. */
    {
        static const struct { const char* name; void (*tw)(void); void (*or_)(void);
                              uint16_t block; } GEN[4] = {
            { "hook_step_gen_cursor_a",     hook_gca_twin, hook_gca_oracle, 0x53F8 },
            { "hook_step_gen_cursor_b",     hook_gcb_twin, hook_gcb_oracle, 0x53FA },
            { "hook_step_dir_gen_cursor_a", hook_dga_twin, hook_dga_oracle, 0x53F8 },
            { "hook_step_dir_gen_cursor_b", hook_dgb_twin, hook_dgb_oracle, 0x53FA },
        };
        int g;
        for (g = 0; g < 4; g++) {
            int sawFwd = 0, sawFwdWrap = 0, sawPlaceWrap = 0, sawBwd = 0, sawBwdUnder = 0;
            int sawBwdPlaceWrap = 0, sawHighPlace = 0, sawZeroRun = 0;
            int genCases = cases / 2;
            register_fixture(GEN[g].name);
            if (!want(GEN[g].name)) continue;
            sub = 0; printed = 0;
            for (t = 0; t < genCases; t++) {
                Cpu6502 c = zero_cpu();
                uint8_t count, place, offset, run;
                int i;

                fill_random(pre);
                c.D = 0;                 /* the geometry path is only ever entered binary */
                c.S = 0xFFu;

                /* the run table: mostly small lengths, one entry in sixteen empty */
                for (i = 0; i < 0x40; i++) {
                    pre[0x5728 + i] = (xs() % 16u) ? (uint8_t)(1u + (xs() % 0x08u)) : 0u;
                    if (pre[0x5728 + i] == 0u) sawZeroRun = 1;
                }
                count = (uint8_t)(1u + (xs() % 0x20u));
                place = (uint8_t)(xs() % count);
                if ((xs() % 8u) == 0u) { place |= 0x80u; sawHighPlace = 1; }
                run = pre[0x5728 + place];
                /* the offset: usually inside the place, but its two boundaries by name */
                switch (xs() % 4u) {
                    case 0:  offset = 0u; break;
                    case 1:  offset = (uint8_t)(run ? run - 1u : 0u); break;
                    default: offset = (uint8_t)xs(); break;
                }
                pre[GEN[g].block]      = place;
                pre[GEN[g].block + 1u] = count;
                pre[GEN[g].block + 5u] = offset;

                /* the direction bit, both ways, plus the engine state $557F's prefix steps */
                pre[0x0025] = (xs() & 1u) ? (uint8_t)(xs() | 0x80u) : (uint8_t)(xs() & 0x7Fu);
                pre[0x59FB] = (uint8_t)(1u + (xs() % 40u));      /* track_dir_count */
                pre[0x0002] = (uint8_t)(xs() % pre[0x59FB]);     /* segment_dir_index */

                c.A = (uint8_t)xs(); c.X = (uint8_t)xs(); c.Y = (uint8_t)xs();
                c.N = xs() & 1; c.V = xs() & 1; c.Z = xs() & 1; c.C = xs() & 1;

                /* which arm — fixture arithmetic */
                if (pre[0x0025] & 0x80u) {
                    sawBwd = 1;
                    if (offset == 0u) {
                        sawBwdUnder = 1;
                        if ((place & 0x7Fu) == 0u) sawBwdPlaceWrap = 1;
                    }
                } else {
                    sawFwd = 1;
                    if ((uint8_t)(offset + 1u) >= run) {
                        sawFwdWrap = 1;
                        if ((uint8_t)(place + 1u) >= count) sawPlaceWrap = 1;
                    }
                }

                sub += diff_run(GEN[g].name, pre, c, GEN[g].tw, GEN[g].or_,
                                LIVE_A | LIVE_X | LIVE_Y | LIVE_S, t, &printed);
            }
            fail += sub;
            printf("%-32s %7d cases, %d mismatch (must be 0)  live=A,X,Y (the stored pair; "
                   "the flags are dead at both call sites)\n", GEN[g].name, genCases, sub);
            if (!(sawFwd && sawFwdWrap && sawPlaceWrap && sawBwd && sawBwdUnder &&
                  sawBwdPlaceWrap && sawHighPlace && sawZeroRun)) {
                printf("VACUOUS: %s missed an arm (fwd %d fwd-wrap %d place-wrap %d bwd %d "
                       "bwd-under %d bwd-place-wrap %d high-bit place %d zero run %d)\n",
                       GEN[g].name, sawFwd, sawFwdWrap, sawPlaceWrap, sawBwd, sawBwdUnder,
                       sawBwdPlaceWrap, sawHighPlace, sawZeroRun);
                fail++;
            }
        }
    }

    /* --------------------------------------- $54F1 / $54EF / $54EB, the section-cursor advance.
       Two fixtures, one per generator state block.  The gate (cur_segment_flags bit 6) has to be
       seen both ways, and the +3 has to be seen wrapping past $FF as well as not — the wrap at
       $78 lives in build_road_section, on the value this returns, so a cursor near $FF is
       reachable here on the very first call of a walk. */
    {
        static const struct { const char* name; void (*tw)(void); void (*or_)(void);
                              uint16_t block; } NSC[2] = {
            { "hook_next_section_cursor_a", hook_nsc_a_twin, hook_nsc_a_oracle, 0x53F8 },
            { "hook_next_section_cursor_b", hook_nsc_b_twin, hook_nsc_b_oracle, 0x53FA },
        };
        int n;
        for (n = 0; n < 2; n++) {
            int sawGated = 0, sawOpen = 0, sawCarry = 0, sawNoCarry = 0, sawFwd = 0, sawBwd = 0;
            int nscCases = cases / 2;
            register_fixture(NSC[n].name);
            if (!want(NSC[n].name)) continue;
            sub = 0; printed = 0;
            for (t = 0; t < nscCases; t++) {
                Cpu6502 c = zero_cpu();
                uint8_t count, cursor;
                int i;

                fill_random(pre);
                c.D = 0;                 /* $12F7's subtree carries no SED (docs/static-map.md) */
                c.S = 0xFFu;

                /* the generator cursor's state, as the $5582 fixture above seeds it */
                for (i = 0; i < 0x40; i++)
                    pre[0x5728 + i] = (xs() % 16u) ? (uint8_t)(1u + (xs() % 0x08u)) : 0u;
                count = (uint8_t)(1u + (xs() % 0x20u));
                pre[NSC[n].block]      = (uint8_t)(xs() % count);
                pre[NSC[n].block + 1u] = count;
                pre[NSC[n].block + 5u] = (xs() % 4u) ? (uint8_t)xs() : 0u;

                /* the gate, both ways by name */
                if (xs() & 1u) { pre[0x0001] = (uint8_t)(xs() | 0x40u); sawGated = 1; }
                else           { pre[0x0001] = (uint8_t)(xs() & 0xBFu); sawOpen  = 1; }

                /* the cursor: mostly a legal walk position, one in four up against $FF */
                cursor = (xs() % 4u) ? (uint8_t)(3u * (xs() % 40u))
                                     : (uint8_t)(0xFDu + (xs() % 3u));
                pre[0x0024] = cursor;
                if ((unsigned)cursor + 3u > 0xFFu) sawCarry = 1; else sawNoCarry = 1;

                pre[0x0025] = (xs() & 1u) ? (uint8_t)(xs() | 0x80u) : (uint8_t)(xs() & 0x7Fu);
                if (pre[0x0025] & 0x80u) sawBwd = 1; else sawFwd = 1;

                c.A = (uint8_t)xs(); c.X = (uint8_t)xs(); c.Y = (uint8_t)xs();
                c.N = xs() & 1; c.V = xs() & 1; c.Z = xs() & 1; c.C = xs() & 1;

                sub += diff_run(NSC[n].name, pre, c, NSC[n].tw, NSC[n].or_,
                                LIVE_A | LIVE_X | LIVE_Y | LIVE_S | LIVE_FLAGS, t, &printed);
            }
            fail += sub;
            printf("%-32s %7d cases, %d mismatch (must be 0)  live=A,X,Y+flags (only A is read "
                   "at $12FB; the rest are replayed and checked anyway)\n",
                   NSC[n].name, nscCases, sub);
            if (!(sawGated && sawOpen && sawCarry && sawNoCarry && sawFwd && sawBwd)) {
                printf("VACUOUS: %s missed an arm (gated %d open %d carry %d no-carry %d "
                       "fwd %d bwd %d)\n", NSC[n].name, sawGated, sawOpen, sawCarry,
                       sawNoCarry, sawFwd, sawBwd);
                fail++;
            }
        }
    }

    /* --------------------------------------- $5472, the generator's direction-vector store.
       All EIGHT octants have to be seen (each one is a different pair of signs and a different
       component order) and both mirror senses; the two scalings' sign comes off the 6502 stack,
       so the gradient multiplier's own path is exercised with negative components too.  The
       heading is swept rather than randomised, because a uniform 16-bit draw would visit each
       octant only ~250 times in 2000 cases and the fixture wants every one of them dense. */
    {
        static const struct { const char* name; void (*tw)(void); void (*or_)(void);
                              uint16_t block; } GDV[5] = {
            { "hook_gen_dir_vector_brands",  hook_gdv_1_twin, hook_gdv_1_oracle, 0x53FA },
            { "hook_gen_dir_vector_doning",  hook_gdv_2_twin, hook_gdv_2_oracle, 0x53FC },
            { "hook_gen_dir_vector_oulton",  hook_gdv_3_twin, hook_gdv_3_oracle, 0x53FA },
            { "hook_gen_dir_vector_snetter", hook_gdv_4_twin, hook_gdv_4_oracle, 0x53FA },
            { "hook_gen_dir_vector_nurburg", hook_gdv_5_twin, hook_gdv_5_oracle, 0x53FC },
        };
        int g;
        for (g = 0; g < 5; g++) {
            int octSeen[8]; int sawMirror = 0, sawStraight = 0, sawZeroComp = 0, sawMinComp = 0;
            int gdvCases = cases / 4, i;
            for (i = 0; i < 8; i++) octSeen[i] = 0;
            register_fixture(GDV[g].name);
            if (!want(GDV[g].name)) continue;
            sub = 0; printed = 0;
            for (t = 0; t < gdvCases; t++) {
                Cpu6502 c = zero_cpu();
                uint8_t hi, lo, oct;

                fill_random(pre);
                c.D = 0;                 /* the generator runs binary (docs/static-map.md) */
                c.S = 0xFFu;

                /* the two quarter-turn tables: real ones hold a quadrant of a circle of radius
                   $78, so keep the magnitudes in range but include 0 and $80 by name */
                for (i = 0; i <= 0x40; i++) {
                    pre[0x57BF + i] = (uint8_t)(xs() % 0x79u);
                    pre[0x58BF + i] = (uint8_t)(xs() % 0x79u);
                    if ((xs() % 32u) == 0u) { pre[0x57BF + i] = 0x00u; sawZeroComp = 1; }
                    if ((xs() % 32u) == 1u) { pre[0x58BF + i] = 0x80u; sawMinComp  = 1; }
                    if (xs() & 1u) pre[0x57BF + i] = (uint8_t)(-(int)pre[0x57BF + i]);
                    if (xs() & 1u) pre[0x58BF + i] = (uint8_t)(-(int)pre[0x58BF + i]);
                }

                /* the heading: sweep the octant, randomise the position inside it */
                oct = (uint8_t)(t & 7u);
                hi  = (uint8_t)((oct << 5) | (xs() & 0x1Fu));
                lo  = (uint8_t)xs();
                pre[GDV[g].block]      = lo;
                pre[GDV[g].block + 1u] = hi;
                pre[GDV[g].block + 2u] = (uint8_t)xs();     /* the gradient, carried through */
                octSeen[oct] = 1;
                if (oct & 1u) sawMirror = 1; else sawStraight = 1;

                pre[0x0002] = (uint8_t)(xs() % 40u);        /* segment_dir_index */
                pre[0x0025] = (uint8_t)xs();                /* track_direction (the tail re-signs) */

                c.A = (uint8_t)xs(); c.X = (uint8_t)xs(); c.Y = (uint8_t)xs();
                c.N = xs() & 1; c.V = xs() & 1; c.Z = xs() & 1; c.C = xs() & 1;

                sub += diff_run(GDV[g].name, pre, c, GDV[g].tw, GDV[g].or_,
                                LIVE_A | LIVE_X | LIVE_Y | LIVE_S | LIVE_FLAGS, t, &printed);
            }
            fail += sub;
            printf("%-32s %7d cases, %d mismatch (must be 0)  live=A,X,Y+flags (X is the "
                   "$5493 TAX, clobbered on purpose)\n", GDV[g].name, gdvCases, sub);
            {
                int allOct = 1;
                for (i = 0; i < 8; i++) if (!octSeen[i]) allOct = 0;
                if (!(allOct && sawMirror && sawStraight && sawZeroComp && sawMinComp)) {
                    printf("VACUOUS: %s missed an arm (all 8 octants %d mirror %d straight %d "
                           "zero component %d $80 component %d)\n", GDV[g].name, allOct,
                           sawMirror, sawStraight, sawZeroComp, sawMinComp);
                    fail++;
                }
            }
        }
    }
    /* --------------------------------------- $55C4, one step of the track generator.
       The fold has to be seen BOTH WAYS ROUND the circuit (track_direction bit 7 signs both the
       turn and the climb) and it has to be seen SKIPPED (place cursor bit 7), and because the
       routine tail-calls $5472 the heading's octant is swept here too — a step that always landed
       in the same octant would leave the vector store's own arms to the $5472 fixtures. */
    {
        static const struct { const char* name; void (*tw)(void); void (*or_)(void);
                              uint16_t block; } GST[5] = {
            { "hook_gen_step_brands",  hook_gstep_1_twin, hook_gstep_1_oracle, 0x53FA },
            { "hook_gen_step_doning",  hook_gstep_2_twin, hook_gstep_2_oracle, 0x53FC },
            { "hook_gen_step_oulton",  hook_gstep_3_twin, hook_gstep_3_oracle, 0x53FA },
            { "hook_gen_step_snetter", hook_gstep_4_twin, hook_gstep_4_oracle, 0x53FA },
            { "hook_gen_step_nurburg", hook_gstep_5_twin, hook_gstep_5_oracle, 0x53FC },
        };
        int g;
        for (g = 0; g < 5; g++) {
            int octSeen[8]; int sawSkip = 0, sawFold = 0, sawRev = 0, sawFwd = 0;
            int sawWrap = 0, sawClimbCarry = 0;
            int gstCases = cases / 4, i;
            for (i = 0; i < 8; i++) octSeen[i] = 0;
            register_fixture(GST[g].name);
            if (!want(GST[g].name)) continue;
            sub = 0; printed = 0;
            for (t = 0; t < gstCases; t++) {
                Cpu6502 c = zero_cpu();
                uint8_t hi, lo, oct, place, dir;

                fill_random(pre);
                c.D = 0;                 /* the generator runs binary (docs/static-map.md) */
                c.S = 0xFFu;

                for (i = 0; i <= 0x40; i++) {           /* $5472's octant sine table */
                    pre[0x57BF + i] = (uint8_t)(xs() % 0x79u);
                    pre[0x58BF + i] = (uint8_t)(xs() % 0x79u);
                    if (xs() & 1u) pre[0x57BF + i] = (uint8_t)(-(int)pre[0x57BF + i]);
                    if (xs() & 1u) pre[0x58BF + i] = (uint8_t)(-(int)pre[0x58BF + i]);
                }

                /* the place cursor: bit 7 set is "places exhausted", which skips the whole fold */
                place = (uint8_t)(xs() % 0x40u);
                if ((t & 3u) == 3u) { place |= 0x80u; sawSkip = 1; } else sawFold = 1;
                pre[GST[g].block - 2u] = place;

                /* one segment's turn and climb, at the place the cursor names */
                pre[(0x5428u) + (place & 0x7Fu)] = (uint8_t)xs();
                pre[(0x5528u) + (place & 0x7Fu)] = (uint8_t)xs();
                pre[(0x5628u) + (place & 0x7Fu)] = (uint8_t)xs();

                oct = (uint8_t)(t & 7u);
                hi  = (uint8_t)((oct << 5) | (xs() & 0x1Fu));
                lo  = (uint8_t)xs();
                pre[GST[g].block]      = lo;
                pre[GST[g].block + 1u] = hi;
                pre[GST[g].block + 2u] = (uint8_t)xs();     /* the running gradient */
                octSeen[oct] = 1;
                /* did the 16-bit heading add wrap, and did the 8-bit gradient add carry?  Both
                   are places a mis-modelled carry would show, so they are arms, not luck. */
                if (((unsigned)lo + (unsigned)pre[(0x5528u) + (place & 0x7Fu)]) > 0xFFu)
                    sawWrap = 1;
                if (((unsigned)pre[GST[g].block + 2u]
                     + (unsigned)pre[(0x5628u) + (place & 0x7Fu)]) > 0xFFu)
                    sawClimbCarry = 1;

                dir = (uint8_t)xs();
                if (t & 1u) { dir |= 0x80u; sawRev = 1; } else { dir &= 0x7Fu; sawFwd = 1; }
                pre[0x0025] = dir;                          /* track_direction */
                pre[0x0002] = (uint8_t)(xs() % 40u);        /* segment_dir_index */

                c.A = (uint8_t)xs(); c.X = (uint8_t)xs(); c.Y = (uint8_t)xs();
                c.N = xs() & 1; c.V = xs() & 1; c.Z = xs() & 1; c.C = xs() & 1;

                sub += diff_run(GST[g].name, pre, c, GST[g].tw, GST[g].or_,
                                LIVE_A | LIVE_X | LIVE_Y | LIVE_S | LIVE_FLAGS, t, &printed);
            }
            fail += sub;
            printf("%-32s %7d cases, %d mismatch (must be 0)  live=A,X,Y+flags (X is restored "
                   "here, and its LDX is what sets the exit N/Z)\n", GST[g].name, gstCases, sub);
            {
                int allOct = 1;
                for (i = 0; i < 8; i++) if (!octSeen[i]) allOct = 0;
                if (!(allOct && sawSkip && sawFold && sawRev && sawFwd && sawWrap
                      && sawClimbCarry)) {
                    printf("VACUOUS: %s missed an arm (all 8 octants %d skip %d fold %d reverse %d "
                           "forward %d heading wrap %d climb carry %d)\n", GST[g].name, allOct,
                           sawSkip, sawFold, sawRev, sawFwd, sawWrap, sawClimbCarry);
                    fail++;
                }
            }
        }
    }
    /* --------------------------------------- $5572, the generator's segment-advance gate.
       Both arms of the boundary gate, and on the taken arm both senses of track_direction (which
       is what step_segment_dir_index steps by) plus its wrap at either end of the index — the
       wrap is the only place the step's two directions read different cells. */
    {
        static const struct { const char* name; void (*tw)(void); void (*or_)(void);
                              uint16_t block; } SADV[5] = {
            { "hook_seg_advance_brands",  hook_sadv_1_twin, hook_sadv_1_oracle, 0x53FA },
            { "hook_seg_advance_doning",  hook_sadv_2_twin, hook_sadv_2_oracle, 0x53FC },
            { "hook_seg_advance_oulton",  hook_sadv_3_twin, hook_sadv_3_oracle, 0x53FA },
            { "hook_seg_advance_snetter", hook_sadv_4_twin, hook_sadv_4_oracle, 0x53FA },
            { "hook_seg_advance_nurburg", hook_sadv_5_twin, hook_sadv_5_oracle, 0x53FC },
        };
        int g;
        for (g = 0; g < 5; g++) {
            int sawGate = 0, sawOpen = 0, sawRev = 0, sawFwd = 0, sawWrapUp = 0, sawWrapDown = 0;
            int sadvCases = cases / 4, i;
            register_fixture(SADV[g].name);
            if (!want(SADV[g].name)) continue;
            sub = 0; printed = 0;
            for (t = 0; t < sadvCases; t++) {
                Cpu6502 c = zero_cpu();
                uint8_t place, dir, count, idx;

                fill_random(pre);
                c.D = 0;                 /* the generator runs binary (docs/static-map.md) */
                c.S = 0xFFu;

                for (i = 0; i <= 0x40; i++) {           /* $5472's octant sine table */
                    pre[0x57BF + i] = (uint8_t)(xs() % 0x79u);
                    pre[0x58BF + i] = (uint8_t)(xs() % 0x79u);
                    if (xs() & 1u) pre[0x57BF + i] = (uint8_t)(-(int)pre[0x57BF + i]);
                    if (xs() & 1u) pre[0x58BF + i] = (uint8_t)(-(int)pre[0x58BF + i]);
                }

                /* the boundary gate */
                if (t & 1u) { pre[0x0001] |= 0x40u; sawGate = 1; }   /* cur_segment_flags */
                else        { pre[0x0001] &= (uint8_t)~0x40u; sawOpen = 1; }

                place = (uint8_t)(xs() % 0x40u);
                if ((t & 7u) == 7u) place |= 0x80u;             /* places exhausted */
                pre[SADV[g].block - 2u] = place;
                pre[0x5428u + (place & 0x7Fu)] = (uint8_t)xs();
                pre[0x5528u + (place & 0x7Fu)] = (uint8_t)xs();
                pre[0x5628u + (place & 0x7Fu)] = (uint8_t)xs();
                pre[SADV[g].block]      = (uint8_t)xs();
                pre[SADV[g].block + 1u] = (uint8_t)xs();
                pre[SADV[g].block + 2u] = (uint8_t)xs();

                /* the direction index and its count: land on both wrap edges on purpose */
                count = (uint8_t)(4u + (xs() % 36u));
                idx   = (uint8_t)(xs() % count);
                if ((t % 6u) == 0u) idx = 0u;                   /* the backward wrap */
                if ((t % 6u) == 1u) idx = (uint8_t)(count - 1u); /* the forward wrap */
                pre[0x0002] = idx;                              /* segment_dir_index */
                pre[0x59FBu] = count;                           /* track_dir_count */

                dir = (uint8_t)xs();
                if (t & 2u) { dir |= 0x80u; sawRev = 1; } else { dir &= 0x7Fu; sawFwd = 1; }
                pre[0x0025] = dir;                              /* track_direction */
                if ((dir & 0x80u) && idx == 0u)                 sawWrapDown = 1;
                if (!(dir & 0x80u) && idx == (uint8_t)(count - 1u)) sawWrapUp = 1;

                c.A = (uint8_t)xs(); c.X = (uint8_t)xs(); c.Y = (uint8_t)xs();
                c.N = xs() & 1; c.V = xs() & 1; c.Z = xs() & 1; c.C = xs() & 1;

                sub += diff_run(SADV[g].name, pre, c, SADV[g].tw, SADV[g].or_,
                                LIVE_A | LIVE_X | LIVE_Y | LIVE_S | LIVE_FLAGS, t, &printed);
            }
            fail += sub;
            printf("%-32s %7d cases, %d mismatch (must be 0)  live=A,X,Y+flags (the no-op arm "
                   "returns A=0 and leaves C/V alone)\n", SADV[g].name, sadvCases, sub);
            if (!(sawGate && sawOpen && sawRev && sawFwd && sawWrapUp && sawWrapDown)) {
                printf("VACUOUS: %s missed an arm (boundary %d no-op %d reverse %d forward %d "
                       "wrap up %d wrap down %d)\n", SADV[g].name, sawGate, sawOpen, sawRev,
                       sawFwd, sawWrapUp, sawWrapDown);
                fail++;
            }
        }
    }
    /* --------------------------------------- $5672, the generator's section seed.
       Both arms of the reverse test (forward runs a whole generator step, reverse runs none),
       both values of the packed byte's bit 1 (which is the $23B3 SMC operand) and of its bit 0
       (the "places exhausted" flag the step then tests), and a Y that ranges over enough
       segments to land in several different sections. */
    {
        static const struct { const char* name; void (*tw)(void); void (*or_)(void);
                              uint16_t block; } GSEED[5] = {
            { "hook_gen_seed_brands",  hook_gseed_1_twin, hook_gseed_1_oracle, 0x53FA },
            { "hook_gen_seed_doning",  hook_gseed_2_twin, hook_gseed_2_oracle, 0x53FC },
            { "hook_gen_seed_oulton",  hook_gseed_3_twin, hook_gseed_3_oracle, 0x53FA },
            { "hook_gen_seed_snetter", hook_gseed_4_twin, hook_gseed_4_oracle, 0x53FA },
            { "hook_gen_seed_nurburg", hook_gseed_5_twin, hook_gseed_5_oracle, 0x53FC },
        };
        int g;
        for (g = 0; g < 5; g++) {
            int sawRev = 0, sawFwd = 0, sawCap = 0, sawNoCap = 0, sawExh = 0, sawOpen = 0;
            int secSeen[32]; int seenSections = 0;
            int gsCases = cases / 4, i;
            register_fixture(GSEED[g].name);
            if (!want(GSEED[g].name)) continue;
            for (i = 0; i < 32; i++) secSeen[i] = 0;
            sub = 0; printed = 0;
            for (t = 0; t < gsCases; t++) {
                Cpu6502 c = zero_cpu();
                uint8_t segment, section, packed, dir, place;

                fill_random(pre);
                c.D = 0;                 /* the generator runs binary (docs/static-map.md) */
                c.S = 0xFFu;

                for (i = 0; i <= 0x40; i++) {           /* $5472's octant sine table */
                    pre[0x57BF + i] = (uint8_t)(xs() % 0x79u);
                    pre[0x58BF + i] = (uint8_t)(xs() % 0x79u);
                    if (xs() & 1u) pre[0x57BF + i] = (uint8_t)(-(int)pre[0x57BF + i]);
                    if (xs() & 1u) pre[0x58BF + i] = (uint8_t)(-(int)pre[0x58BF + i]);
                }

                segment = (uint8_t)(xs() % 0xF8u);      /* 31 sections of 8 */
                section = (uint8_t)(segment >> 3);
                secSeen[section & 31u] = 1;

                pre[0x5905u + segment] = (uint8_t)xs();  /* the direction-basis entry */
                pre[0x5846u + section] = (uint8_t)xs();  /* seeded heading low  */
                pre[0x5864u + section] = (uint8_t)xs();  /* seeded heading high */
                pre[0x5828u + section] = (uint8_t)xs();  /* seeded gradient     */

                /* the packed byte: bit 1 is the $23B3 cap, bit 0 the places-exhausted flag,
                   bits 2..7 the place cursor the generator step then indexes with */
                packed = (uint8_t)(xs() & 0xFCu);
                if (t & 1u) { packed |= 2u; sawCap = 1; } else sawNoCap = 1;
                if ((t & 6u) == 0u) { packed |= 1u; sawExh = 1; } else sawOpen = 1;
                pre[0x5882u + section] = packed;

                place = (uint8_t)(packed >> 2);
                pre[0x5428u + place] = (uint8_t)xs();   /* the step's per-place turn and climb */
                pre[0x5528u + place] = (uint8_t)xs();
                pre[0x5628u + place] = (uint8_t)xs();

                dir = (uint8_t)xs();
                if (t & 8u) { dir |= 0x80u; sawRev = 1; } else { dir &= 0x7Fu; sawFwd = 1; }
                pre[0x0025] = dir;                      /* track_direction */

                c.A = (uint8_t)xs(); c.X = (uint8_t)xs(); c.Y = segment;
                c.N = xs() & 1; c.V = xs() & 1; c.Z = xs() & 1; c.C = xs() & 1;

                sub += diff_run(GSEED[g].name, pre, c, GSEED[g].tw, GSEED[g].or_,
                                LIVE_A | LIVE_X | LIVE_Y | LIVE_S | LIVE_FLAGS, t, &printed);
            }
            fail += sub;
            for (i = 0; i < 32; i++) seenSections += secSeen[i];
            printf("%-32s %7d cases, %d mismatch (must be 0)  live=A,X,Y+flags (and $23B3, the "
                   "runtime SMC operand)\n", GSEED[g].name, gsCases, sub);
            if (!(sawRev && sawFwd && sawCap && sawNoCap && sawExh && sawOpen
                  && seenSections >= 8)) {
                printf("VACUOUS: %s missed an arm (reverse %d forward %d cap-off %d cap-on %d "
                       "exhausted %d open %d sections %d)\n", GSEED[g].name, sawRev, sawFwd,
                       sawCap, sawNoCap, sawExh, sawOpen, seenSections);
                fail++;
            }
        }
    }
    /* --------------------------------------- $5A1B, the cursor step plus the vector rebuild.
       The union of the two halves' arms: the cursor's four (forward, forward place advance,
       backward, backward underflow) and the vector's octant sweep, since the cursor decides
       which heading the vector is then built from. */
    {
        static const struct { const char* name; void (*tw)(void); void (*or_)(void);
                              uint16_t block; } AGP[5] = {
            { "hook_advance_gen_place_brands",  hook_agp_1_twin, hook_agp_1_oracle, 0x53FA },
            { "hook_advance_gen_place_doning",  hook_agp_2_twin, hook_agp_2_oracle, 0x53FC },
            { "hook_advance_gen_place_oulton",  hook_agp_3_twin, hook_agp_3_oracle, 0x53FA },
            { "hook_advance_gen_place_snetter", hook_agp_4_twin, hook_agp_4_oracle, 0x53FA },
            { "hook_advance_gen_place_nurburg", hook_agp_5_twin, hook_agp_5_oracle, 0x53FC },
        };
        int g;
        for (g = 0; g < 5; g++) {
            int sawFwd = 0, sawFwdWrap = 0, sawBwd = 0, sawBwdUnder = 0, sawZeroRun = 0;
            int octSeen[8]; int seenOct = 0;
            int agpCases = cases / 4, i;
            register_fixture(AGP[g].name);
            if (!want(AGP[g].name)) continue;
            for (i = 0; i < 8; i++) octSeen[i] = 0;
            sub = 0; printed = 0;
            for (t = 0; t < agpCases; t++) {
                Cpu6502 c = zero_cpu();
                uint16_t cursor = (uint16_t)(AGP[g].block - 2u);
                uint8_t count, place, offset, run, angleLo, angleHi;
                uint16_t nine;

                fill_random(pre);
                c.D = 0;                 /* the geometry path is only ever entered binary */
                c.S = 0xFFu;

                for (i = 0; i <= 0x40; i++) {           /* $5472's octant sine table */
                    pre[0x57BF + i] = (uint8_t)(xs() % 0x79u);
                    pre[0x58BF + i] = (uint8_t)(xs() % 0x79u);
                    if (xs() & 1u) pre[0x57BF + i] = (uint8_t)(-(int)pre[0x57BF + i]);
                    if (xs() & 1u) pre[0x58BF + i] = (uint8_t)(-(int)pre[0x58BF + i]);
                }

                /* the cursor's run table, with the odd empty place the 6502 walk allows */
                for (i = 0; i < 0x40; i++) {
                    pre[0x5728 + i] = (xs() % 16u) ? (uint8_t)(1u + (xs() % 0x08u)) : 0u;
                    if (pre[0x5728 + i] == 0u) sawZeroRun = 1;
                }
                count  = (uint8_t)(1u + (xs() % 0x20u));
                place  = (uint8_t)(xs() % count);
                run    = pre[0x5728 + place];
                offset = (xs() & 1u) ? (uint8_t)(run ? run - 1u : 0u) : (uint8_t)(xs() % 8u);
                pre[cursor]      = place;
                pre[cursor + 1u] = count;
                pre[cursor + 5u] = offset;

                /* the heading the vector is built from — sweep the octants */
                angleHi = (uint8_t)((t & 7u) << 5 | (xs() & 0x1Fu));
                angleLo = (uint8_t)xs();
                pre[AGP[g].block]      = angleLo;
                pre[AGP[g].block + 1u] = angleHi;
                pre[AGP[g].block + 2u] = (uint8_t)xs();   /* the gradient it stores and returns */
                nine = (uint16_t)((angleHi << 1) | (angleLo >> 7));
                octSeen[(nine >> 6) & 7u] = 1;

                pre[0x0025] = (xs() & 1u) ? (uint8_t)(xs() | 0x80u) : (uint8_t)(xs() & 0x7Fu);
                pre[0x59FB] = (uint8_t)(1u + (xs() % 40u));      /* track_dir_count */
                pre[0x0002] = (uint8_t)(xs() % pre[0x59FB]);     /* segment_dir_index */

                if (pre[0x0025] & 0x80u) {
                    sawBwd = 1;
                    if (offset == 0u) sawBwdUnder = 1;
                } else {
                    sawFwd = 1;
                    if ((uint8_t)(offset + 1u) >= run) sawFwdWrap = 1;
                }

                c.A = (uint8_t)xs(); c.X = (uint8_t)xs(); c.Y = (uint8_t)xs();
                c.N = xs() & 1; c.V = xs() & 1; c.Z = xs() & 1; c.C = xs() & 1;

                sub += diff_run(AGP[g].name, pre, c, AGP[g].tw, AGP[g].or_,
                                LIVE_A | LIVE_X | LIVE_Y | LIVE_S | LIVE_FLAGS, t, &printed);
            }
            fail += sub;
            for (i = 0; i < 8; i++) seenOct += octSeen[i];
            printf("%-32s %7d cases, %d mismatch (must be 0)  live=A,X,Y+flags ($5472's exit, "
                   "which is this routine's)\n", AGP[g].name, agpCases, sub);
            if (!(sawFwd && sawFwdWrap && sawBwd && sawBwdUnder && sawZeroRun && seenOct == 8)) {
                printf("VACUOUS: %s missed an arm (fwd %d fwd-wrap %d bwd %d bwd-under %d "
                       "zero run %d octants %d)\n", AGP[g].name, sawFwd, sawFwdWrap, sawBwd,
                       sawBwdUnder, sawZeroRun, seenOct);
                fail++;
            }
        }
    }
    /* --------------------------------------- the three cross-circuit one-line bodies.
       One twin each, so ONE fixture each — but every circuit's dispatch entry is driven through
       it, because the thing that could differ between them is the entry, not the body. */
    {
        static const struct { const char* name; void (*tw)(void); void (*or_)(void); } ONE[15] = {
            { "hook_horizon_half_width_scale", hook_hhw_1_twin, hook_hhw_1_oracle },
            { "hook_horizon_half_width_scale", hook_hhw_2_twin, hook_hhw_2_oracle },
            { "hook_horizon_half_width_scale", hook_hhw_3_twin, hook_hhw_3_oracle },
            { "hook_horizon_half_width_scale", hook_hhw_4_twin, hook_hhw_4_oracle },
            { "hook_abs_by_track_direction",   hook_abd_1_twin, hook_abd_1_oracle },
            { "hook_abs_by_track_direction",   hook_abd_2_twin, hook_abd_2_oracle },
            { "hook_abs_by_track_direction",   hook_abd_3_twin, hook_abd_3_oracle },
            { "hook_abs_by_track_direction",   hook_abd_4_twin, hook_abd_4_oracle },
            { "hook_abs_by_track_direction",   hook_abd_5_twin, hook_abd_5_oracle },
            { "hook_scale_entry_by_gradient",  hook_seg_1_twin, hook_seg_1_oracle },
            { "hook_scale_entry_by_gradient",  hook_seg_2_twin, hook_seg_2_oracle },
            { "hook_scale_entry_by_gradient",  hook_seg_3_twin, hook_seg_3_oracle },
            { "hook_scale_entry_by_gradient",  hook_seg_4_twin, hook_seg_4_oracle },
            { "hook_scale_entry_by_gradient",  hook_seg_5_twin, hook_seg_5_oracle },
            { "hook_horizon_half_width_abs_doning", hook_hhwd_twin, hook_hhwd_oracle },
        };
        /* ⭐ Donington's $57B6 rides this fixture rather than one of its own: it IS the horizon
           scale with an abs8 in front, and the N-decorrelated cases below are exactly what
           tells the flag test from a bit-7 test. */
        static const char* const ONE_NAMES[4] = { "hook_horizon_half_width_scale",
                                                  "hook_abs_by_track_direction",
                                                  "hook_scale_entry_by_gradient",
                                                  "hook_horizon_half_width_abs_doning" };
        int n;
        for (n = 0; n < 4; n++) {
            int sawNeg = 0, sawPos = 0, sawZero = 0, sawFwd = 0, sawBwd = 0, sawNoAdd = 0;
            int oneCases = cases / 4, e;
            register_fixture(ONE_NAMES[n]);
            if (!want(ONE_NAMES[n])) continue;
            sub = 0; printed = 0;
            for (t = 0; t < oneCases; t++) {
                Cpu6502 c = zero_cpu();
                uint8_t value, dir;

                fill_random(pre);
                c.D = 0;                 /* none of the eight SED sites reach here */
                c.S = 0xFFu;

                /* the value, with its two edges by name: $00 (the abs8 no-op that still sets Z,
                   and the multiplier that adds nothing) and $80 (the negate that overflows) */
                switch (xs() % 6u) {
                    case 0:  value = 0x00u; sawZero = 1; break;
                    case 1:  value = 0x80u; break;
                    default: value = (uint8_t)xs(); break;
                }
                if (value & 0x80u) sawNeg = 1; else sawPos = 1;
                if (value == 0u) sawNoAdd = 1;

                dir = (uint8_t)xs();
                if (xs() & 1u) { dir |= 0x80u; sawBwd = 1; } else { dir &= 0x7Fu; sawFwd = 1; }
                pre[0x0025] = dir;                       /* track_direction */
                pre[0x0075] = (uint8_t)xs();             /* math_hi — the gradient multiplier */
                pre[0x0074] = (uint8_t)xs();             /* math_lo */

                c.A = value; c.X = (uint8_t)xs(); c.Y = (uint8_t)xs();
                /* ⭐ N is DECORRELATED from bit 7 of A on a third of the cases: abs8 and the
                   gradient tail both test the flag, not the value, and the two hooks that reach
                   them are entered from 6502 code whose last op may have set N from elsewhere. */
                c.N = (xs() % 3u) ? (uint8_t)((value >> 7) & 1u) : (uint8_t)(xs() & 1u);
                c.V = xs() & 1; c.Z = xs() & 1; c.C = xs() & 1;

                for (e = 0; e < 15; e++) {
                    if (strcmp(ONE[e].name, ONE_NAMES[n]) != 0) continue;
                    sub += diff_run(ONE_NAMES[n], pre, c, ONE[e].tw, ONE[e].or_,
                                    LIVE_A | LIVE_X | LIVE_Y | LIVE_S | LIVE_FLAGS, t, &printed);
                }
            }
            fail += sub;
            printf("%-32s %7d cases x every circuit's entry, %d mismatch (must be 0)  "
                   "live=A,X,Y+flags\n", ONE_NAMES[n], oneCases, sub);
            if (!(sawNeg && sawPos && sawZero && sawFwd && sawBwd && sawNoAdd)) {
                printf("VACUOUS: %s missed an arm (neg %d pos %d zero %d fwd %d bwd %d "
                       "no-add %d)\n", ONE_NAMES[n], sawNeg, sawPos, sawZero, sawFwd, sawBwd,
                       sawNoAdd);
                fail++;
            }
        }
    }
    return fail;
}

